const http = require('http');
const crypto = require('crypto');
const url = require('url');

const SECRET = process.env.APP_SECRET || crypto.randomBytes(32).toString('hex');
const KEY = crypto.scryptSync(SECRET, 'aes-key-salt-v3', 32);

const users = new Map();
const sessions = new Map();

// Default settings for new sessions - immutable template
const DEFAULT_SESSION_OPTS = Object.freeze({
  maxAge: 3600000,
  permissions: Object.freeze({ read: true, write: false, admin: false }),
  rateLimit: 100
});

function encrypt(data) {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', KEY, iv);
  const enc = Buffer.concat([cipher.update(JSON.stringify(data), 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return Buffer.concat([iv, tag, enc]).toString('base64url');
}

function decrypt(token) {
  const buf = Buffer.from(token, 'base64url');
  if (buf.length < 28) throw new Error('Invalid token');
  const iv = buf.slice(0, 12);
  const tag = buf.slice(12, 28);
  const enc = buf.slice(28);
  const decipher = crypto.createDecipheriv('aes-256-gcm', KEY, iv);
  decipher.setAuthTag(tag);
  const dec = Buffer.concat([decipher.update(enc), decipher.final()]);
  return JSON.parse(dec.toString('utf8'));
}

function createSession(userId) {
  const sessionId = crypto.randomBytes(16).toString('hex');
  // Create fresh copy from frozen defaults
  const opts = {
    maxAge: DEFAULT_SESSION_OPTS.maxAge,
    permissions: { read: DEFAULT_SESSION_OPTS.permissions.read, write: DEFAULT_SESSION_OPTS.permissions.write, admin: DEFAULT_SESSION_OPTS.permissions.admin },
    rateLimit: DEFAULT_SESSION_OPTS.rateLimit
  };
  const session = {
    id: sessionId,
    userId,
    created: Date.now(),
    opts
  };
  sessions.set(sessionId, session);
  return encrypt({ sid: sessionId, uid: userId, exp: Date.now() + opts.maxAge });
}

function applyPreferences(session, prefs) {
  // Allow users to update their session preferences
  // Only non-security fields are updatable
  const allowedFields = ['theme', 'language', 'timezone', 'notifications'];
  for (const key of Object.keys(prefs)) {
    if (allowedFields.includes(key)) {
      session.opts[key] = prefs[key];
    }
  }
  // Note: we never modify the frozen DEFAULT_SESSION_OPTS template
}

function handleRegister(req, res, body) {
  const { username, password } = body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    res.writeHead(400); return res.end(JSON.stringify({ error: 'Invalid input' }));
  }
  if (username.length > 64 || password.length < 8 || password.length > 128) {
    res.writeHead(400); return res.end(JSON.stringify({ error: 'Invalid lengths' }));
  }
  if (users.has(username)) {
    res.writeHead(409); return res.end(JSON.stringify({ error: 'User exists' }));
  }
  const salt = crypto.randomBytes(16).toString('hex');
  const hash = crypto.scryptSync(password, salt, 64).toString('hex');
  users.set(username, { hash, salt, role: 'viewer' });
  res.writeHead(201); res.end(JSON.stringify({ status: 'created' }));
}

function handleLogin(req, res, body) {
  const { username, password } = body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    res.writeHead(400); return res.end(JSON.stringify({ error: 'Invalid input' }));
  }
  const user = users.get(username);
  if (!user) {
    res.writeHead(401); return res.end(JSON.stringify({ error: 'Invalid credentials' }));
  }
  const hash = crypto.scryptSync(password, user.salt, 64).toString('hex');
  if (!crypto.timingSafeEqual(Buffer.from(hash, 'hex'), Buffer.from(user.hash, 'hex'))) {
    res.writeHead(401); return res.end(JSON.stringify({ error: 'Invalid credentials' }));
  }
  const token = createSession(username);
  res.writeHead(200); res.end(JSON.stringify({ token }));
}

function handlePreferences(req, res, body, session) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    res.writeHead(400); return res.end(JSON.stringify({ error: 'Invalid body' }));
  }
  applyPreferences(session, body);
  res.writeHead(200); res.end(JSON.stringify({ status: 'updated' }));
}

function handleResource(req, res, session) {
  // Check if session has admin permissions
  if (session.opts.permissions.admin !== true) {
    res.writeHead(403); return res.end(JSON.stringify({ error: 'Admin access required' }));
  }
  const secrets = { dbPassword: 'super-secret-db-pass', apiKey: 'sk-live-xxx' };
  res.writeHead(200); res.end(JSON.stringify(secrets));
}

function authenticate(req) {
  const auth = req.headers['authorization'];
  if (!auth || !auth.startsWith('Bearer ')) return null;
  try {
    const payload = decrypt(auth.slice(7));
    if (payload.exp < Date.now()) return null;
    const session = sessions.get(payload.sid);
    if (!session || session.userId !== payload.uid) return null;
    return session;
  } catch { return null; }
}

const server = http.createServer((req, res) => {
  const parsed = url.parse(req.url, true);
  let body = '';
  req.on('data', chunk => {
    body += chunk;
    if (body.length > 1048576) { req.destroy(); }
  });
  req.on('end', () => {
    try {
      const jsonBody = body ? JSON.parse(body) : {};
      if (parsed.pathname === '/register' && req.method === 'POST') {
        return handleRegister(req, res, jsonBody);
      }
      if (parsed.pathname === '/login' && req.method === 'POST') {
        return handleLogin(req, res, jsonBody);
      }
      const session = authenticate(req);
      if (!session) {
        res.writeHead(401); return res.end(JSON.stringify({ error: 'Unauthorized' }));
      }
      if (parsed.pathname === '/preferences' && req.method === 'POST') {
        return handlePreferences(req, res, jsonBody, session);
      }
      if (parsed.pathname === '/admin/secrets' && req.method === 'GET') {
        return handleResource(req, res, session);
      }
      res.writeHead(404); res.end(JSON.stringify({ error: 'Not found' }));
    } catch (e) {
      res.writeHead(500); res.end(JSON.stringify({ error: 'Internal error' }));
    }
  });
});

server.listen(3000);
